mapper.select:
SELECT COUNT(*) FROM sys_role_menu rm JOIN sys_role r ON r.id=rm.role_id AND r.deleted=FALSE
WHERE rm.menu_id IN (
    WITH RECURSIVE subtree AS (
        SELECT id FROM sys_menu WHERE id=#{id}
        UNION SELECT m.id FROM sys_menu m JOIN subtree s ON m.parent_id=s.id WHERE m.deleted=FALSE
    ) SELECT id FROM subtree
) AND rm.deleted=FALSE
